Clase Caja
    Publico Definir contenido Como Entero;
FinClase

SubProceso Intercambiar(cajaA Como Caja, cajaB Como Caja)
    Definir auxiliar Como Entero;
    auxiliar <- cajaA.contenido;
    cajaA.contenido <- cajaB.contenido;
    cajaB.contenido <- auxiliar;
FinSubProceso

Proceso EjecutarIntercambioDeCajas
    Definir v1 Como Entero;
    Definir v2 Como Entero;
    Definir caja1 Como Caja;
    Definir caja2 Como Caja;
    Leer v1;
    Leer v2;
    caja1 <- Nuevo Caja();
    caja2 <- Nuevo Caja();
    caja1.contenido <- v1;
    caja2.contenido <- v2;
    Intercambiar(caja1, caja2);
    Escribir caja1.contenido;
    Escribir caja2.contenido;
FinProceso
